export class RapierObstacleBodies implements ObstacleBodyFactory {
  constructor(private readonly world: RAPIER.World) {}

  create(descriptor: ObstacleDescriptor): ObstacleBody {
    const halfExt = halfExtents(descriptor);
    const colliderDesc = RAPIER.ColliderDesc.cuboid(halfExt.x, halfExt.y, halfExt.z);
    
    let rbDesc: RAPIER.RigidBodyDesc;
    if (descriptor.type === 'spinner' || descriptor.type === 'windmill' || descriptor.type === 'gate' || descriptor.type === 'platform') {
      rbDesc = RAPIER.RigidBodyDesc.kinematicPositionBased();
    } else {
      rbDesc = RAPIER.RigidBodyDesc.fixed();
    }
    
    const rb = this.world.createRigidBody(rbDesc);
    const collider = this.world.createCollider(colliderDesc, rb);
    
    const pos = descriptor.transform.position;
    const rot = descriptor.transform.rotation || { x: 0, y: 0, z: 0, w: 1 };
    rb.setTranslation(pos, true);
    rb.setRotation(rot, true);

    return {
      setPose: (pose: ObstaclePose) => {
        rb.setTranslation(pose.position, true);
        rb.setRotation(pose.rotation, true);
      },
      setEnabled: (enabled: boolean) => {
        collider.setEnabled(enabled);
      },
      dispose: () => {
        this.world.removeRigidBody(rb);
      }
    };
  }
}
